            vars['hardship_resume_phase'] = phase
            vars['hardship_proposal'] = dict(date_text=dt, amount_text=amount_text, product_scope=scope, amount_scope=amount_scope, proposal_items=items) if dt or amount_text or items else dict()
            vars['phase'] = 'support_offer'
            collection_say('I am sorry you are going through this. Would you like me to connect you with the customer support team?')
        elif event == 'restructuring' and vars.get('hardship_active') == 'yes':
            vars['phase'] = 'support_offer'
            collection_say('Would you like me to connect you with the customer support team?')
        elif phase == 'support_offer' and event in ['accept', 'confirm']:
            request_transfer('support')
        elif phase == 'support_offer' and event in ['refuse', 'nonanswer', 'stop']:
            for row in ledger:
                if row['status'] in ['open', 'agreed']:
                    row['status'] = 'hardship'
            advance()
        elif event == 'restructuring':
