        elif event == 'question':
            vars['answer_account_question'] = 'yes'
            collection_say(str(vars.get('collection_prompt', '')))
        elif event in ['ai', 'scam']:
            prefix = "I am Freya Bank's digital assistant. " if event == 'ai' else "You can verify this call by phoning Freya Bank's customer service number. "
            collection_say(prefix + str(vars.get('collection_prompt', '')))
        elif selected and any(r['status'] == 'recorded' for r in selected):
            collection_say('A recorded promise cannot be changed or cancelled during this call. You can change it in the mobile app.')
        elif event in ['paid', 'dispute']:
            if not selected:
                remember_input(event)
                collection_say('Which product do you mean?')
