                        break
                    rows = resolve_scope(item.get('scope', ''))
                    if len(rows) != 1:
                        scope_error = True
                        break
                    terms[rows[0]['product_id']] = dict(date_text=str(item.get('date_text', dt) or dt), amount_text=str(item.get('amount_text', '') or ''))
                selected = [r for r in ledger if r['product_id'] in terms]
            else:
                for row in selected:
