                remember_input(event)
                collection_say('Does that amount apply to a particular product, or to each product separately?')
            else:
                shared = not items and len(selected) > 1 and (scope.lower() == 'all' or (phase == 'all' and not scope))
                prepared = []
                clarification = ''
                shared_vague = shared and dt and parse_day(dt)[1] == 'vague'
                if shared_vague and not all(int(r.get('vague_count', 0)) >= 1 for r in selected):
                    for row in selected:
                        row['vague_count'] = 1
                        row['waiting_exact'] = 'yes'
                    clarification = 'What exact day do you mean?'
                for row in selected:
                    if clarification:
                        break
                    term = terms[row['product_id']]
                    proposed_amount = term['amount_text']
                    try:
                        amount = number(proposed_amount) if proposed_amount else row.get('offer_amount', row['past_due'])
                    except Exception:
                        clarification = 'Please confirm the amount you proposed.'
                        break
                    proposed_date = term['date_text']
                    day, quality = parse_day(proposed_date) if proposed_date else (row.get('offer_date', next_business(today).isoformat()), 'exact')
                    deadline_offer = False
                    adjustment = ''
                    if quality == 'vague':
                        if int(row.get('vague_count', 0)) < 1:
                            row['vague_count'] = 1
                            row['waiting_exact'] = 'yes'
                            clarification = 'What exact day do you mean?'
                            break
                        day = row['deadline']
                        deadline_offer = not shared
                        adjustment = 'The latest date I can record for your ' + row['label'] + ' is ' + speak_day(day) + '. '
                    elif quality != 'exact':
                        clarification = 'Please give the exact payment day, month and year.'
                        break
                    else:
                        parsed = datetime.date.fromisoformat(day)
                        if parsed < today:
                            clarification = 'The payment date must be today or later. What exact day do you mean?'
                            break
                        if day > row['deadline']:
                            day = row['deadline']
                            deadline_offer = not shared
                            adjustment = 'For your ' + row['label'] + ', the latest date I can record is ' + speak_day(day) + '. '
                        elif not business(parsed):
