                    prepared.append(dict(row=row, amount=amount, date=day, proposed_amount=proposed_amount, deadline_offer=deadline_offer, adjustment=adjustment))
                if clarification:
                    remember_input(event)
                    collection_say(clarification)
                else:
                    adjustments = []
                    for entry in prepared:
                        row = entry['row']
                        amount = entry['amount']
                        day = entry['date']
                        row['confirmed'] = 'no'
                        row['status'] = 'open'
                        row['waiting_exact'] = 'no'
                        adjustment = entry['adjustment']
