                    row['status'] = 'agreed'
            advance('Today is not a business day; I can record the next business day. ' if not business(today) else '')
        elif phase == 'product' and event in ['accept', 'confirm'] and current and current.get('offer_date'):
            current['status'] = 'agreed'
            advance()
        elif event in ['refuse', 'nonanswer', 'stop']:
            if event == 'stop':
                vars['talk_refusals'] = int(vars['talk_refusals']) + 1
            if int(vars['talk_refusals']) >= 2:
                for row in ledger:
                    if row['status'] in ['open', 'agreed']:
                        row['status'] = 'refused'
                advance()
            elif phase == 'all':
