            else:
                targets = selected or ([current] if current else [r for r in ledger if r['status'] == 'agreed'])
                for row in targets:
                    if row.get('offer_date'):
                        row.setdefault('rejected', []).append(money(row['offer_amount']) + '|' + row['offer_date'])
                    row['status'] = 'open'
                    row.pop('question', None)
                    persuasion(row)
                advance()
        else:
            collection_say(str(vars.get('collection_prompt', 'Please clarify your answer.')))
    vars['ledger'] = ledger
    vars['successful_notes'] = notes
    vars['ledger_text'] = json.dumps(ledger)
